use super::*;
use std::{collections::{BTreeMap,HashMap,HashSet},sync::{Mutex,atomic::{AtomicBool,Ordering}},time::{Duration,Instant}};
const ABSOLUTE:Duration=Duration::from_secs(600);
const IDLE:Duration=Duration::from_secs(300);
struct Session{owner:Owner,kind:Kind,created:Instant,touched:Instant,reservation:usize,inflight:bool,prepared:Option<Arc<PreparedPreview>>,state:State}
struct Registry{sessions:BTreeMap<String,Session>,owners:HashMap<String,Owner>,loading:HashSet<String>,dialog:bool}
pub(crate) struct ImportService{pub(crate) repository:Repository,pub(crate) qa:bool,registry:Mutex<Registry>,heavy:AtomicBool}
pub(crate) struct Work(Arc<ImportService>);impl Drop for Work{fn drop(&mut self){self.0.heavy.store(false,Ordering::Release);}}
impl ImportService{
    pub fn new(repository:Repository,qa:bool)->Self{Self{repository,qa,registry:Mutex::new(Registry{sessions:BTreeMap::new(),owners:HashMap::new(),loading:HashSet::new(),dialog:false}),heavy:AtomicBool::new(false)}}
    pub fn work(self:&Arc<Self>)->Result<Work>{self.heavy.compare_exchange(false,true,Ordering::AcqRel,Ordering::Acquire).map_err(|_|fail("BUSY"))?;Ok(Work(self.clone()))}
    // Native availability only; each execution and commit still requires its live guards.
    pub fn enabled(&self)->Result<()>{self.management_enabled()}
    pub fn management_enabled(&self)->Result<()>{self.repository.management_enabled(self.qa).map_err(Into::into)}
    pub fn info(&self,repository:Option<crate::fiscal_repository::Status>)->Info{let can_import=self.management_enabled().is_ok();Info{qa:self.qa,can_import,message:host_context::message(self.qa,can_import),repository}}
    pub fn owner(&self,label:&str,handle:usize)->Result<Owner>{if label!="main"||handle==0{return Err(fail("UNAUTHORIZED_WINDOW"));}let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;if r.loading.contains(label){return Err(fail("DOCUMENT_NOT_READY"));}if let Some(o)=r.owners.get(label){if o.native_handle==handle{return Ok(o.clone());}}let o=Owner{label:label.into(),native_handle:handle,incarnation:uuid::Uuid::new_v4().to_string()};r.owners.insert(label.into(),o.clone());Ok(o)}
    pub(crate) fn with_owner_guard<T,E,F>(&self,owner:&Owner,action:F)->std::result::Result<T,E> where E:From<Error>,F:FnOnce()->std::result::Result<T,E>{let registry=self.registry.lock().map_err(|_|E::from(fail("UNAVAILABLE")))?;if registry.loading.contains(&owner.label)||registry.owners.get(&owner.label)!=Some(owner){return Err(E::from(fail("SESSION_OWNER_MISMATCH")));}action()}
    pub fn navigation(&self,label:&str,loading:bool){if let Ok(mut r)=self.registry.lock(){if loading{r.loading.insert(label.into());r.owners.remove(label);for s in r.sessions.values_mut().filter(|s|s.owner.label==label){if s.state.phase!="confirming"&&s.state.phase!="unknown"&&s.state.phase!="committed"{s.state.phase="cancelled".into();s.prepared=None;if !s.inflight{s.reservation=0;}}}}else{r.loading.remove(label);}}}
    fn expire(s:&mut Session){if !s.inflight&&matches!(s.state.phase.as_str(),"ready"|"stale")&&(s.created.elapsed()>=ABSOLUTE||s.touched.elapsed()>=IDLE){s.state.phase="expired".into();s.state.preview_nonce=None;s.prepared=None;s.reservation=0;}}
    fn check<'a>(r:&'a mut Registry,id:&str,o:&Owner)->Result<&'a mut Session>{if r.owners.get(&o.label)!=Some(o){return Err(fail("SESSION_OWNER_MISMATCH"));}let s=r.sessions.get_mut(id).ok_or_else(||fail("SESSION_UNKNOWN"))?;if s.owner!=*o{return Err(fail("SESSION_OWNER_MISMATCH"));}Self::expire(s);Ok(s)}
    pub fn begin(&self,o:&Owner,kind:Kind)->Result<State>{self.management_enabled()?;let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;for s in r.sessions.values_mut(){Self::expire(s);}if r.dialog{return Err(fail("SELECTOR_BUSY"));}if r.owners.get(&o.label)!=Some(o){return Err(fail("SESSION_OWNER_MISMATCH"));}let count=r.sessions.values().filter(|s|s.reservation>0).count();let owned=r.sessions.values().filter(|s|s.reservation>0&&s.owner==*o).count();let reserved=if kind==Kind::Trust{4*1024*1024}else{2*1024*1024};if count>=4||owned>=2||r.sessions.values().map(|s|s.reservation).sum::<usize>()+reserved>16*1024*1024{return Err(fail("SESSION_CAPACITY"));}if r.sessions.len()>=128{let old=r.sessions.iter().find(|(_,s)|s.reservation==0&&!s.inflight).map(|(id,_)|id.clone());if let Some(id)=old{r.sessions.remove(&id);}else{return Err(fail("SESSION_CAPACITY"));}}
        let state=State{session_id:uuid::Uuid::new_v4().to_string(),operation_id:uuid::Uuid::new_v4().to_string(),phase:"selecting".into(),error:None,preview_nonce:None,summary:None,receipt:None};r.sessions.insert(state.session_id.clone(),Session{owner:o.clone(),kind,created:Instant::now(),touched:Instant::now(),reservation:reserved,inflight:true,prepared:None,state:state.clone()});r.dialog=true;Ok(state)
    }
    pub fn get(&self,o:&Owner,id:&str)->Result<State>{let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;Ok(Self::check(&mut r,id,o)?.state.clone())}
    pub fn cancel(&self,o:&Owner,id:&str)->Result<State>{let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=Self::check(&mut r,id,o)?;if !matches!(s.state.phase.as_str(),"confirming"|"unknown"|"committed"){s.state.phase="cancelled".into();s.state.preview_nonce=None;s.prepared=None;if !s.inflight{s.reservation=0;}}Ok(s.state.clone())}
    pub fn selector_closed(&self){if let Ok(mut r)=self.registry.lock(){r.dialog=false;}}
    pub fn finish_error(&self,id:&str,code:&str){if let Ok(mut r)=self.registry.lock(){if let Some(s)=r.sessions.get_mut(id){s.inflight=false;if !matches!(s.state.phase.as_str(),"cancelled"|"expired"){s.state.phase=if code=="NO_SELECTION"{"no-selection"}else if code=="SESSION_EXPIRED"{"expired"}else{"rejected"}.into();s.state.error=Some(code.into());}s.prepared=None;s.reservation=0;}}}
    pub fn selected(self:&Arc<Self>,o:&Owner,id:&str,buffers:Vec<Vec<u8>>)->Result<()>{let _work=self.work()?;let kind={let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=Self::check(&mut r,id,o)?;if !matches!(s.state.phase.as_str(),"selecting"|"verifying"){return Err(fail("SESSION_CANCELLED"));}if s.created.elapsed()>=ABSOLUTE||s.touched.elapsed()>=IDLE{return Err(fail("SESSION_EXPIRED"));}s.state.phase="verifying".into();s.inflight=true;s.kind};
        let prepared=self.repository.prepare_import(&buffers,kind==Kind::Trust)?;let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=Self::check(&mut r,id,o)?;s.inflight=false;if s.state.phase=="cancelled"{s.reservation=0;return Ok(());}if s.created.elapsed()>=ABSOLUTE||s.touched.elapsed()>=IDLE{s.state.phase="expired".into();s.reservation=0;return Ok(());}s.state.phase="ready".into();s.state.error=None;s.state.preview_nonce=Some(uuid::Uuid::new_v4().to_string());s.state.summary=Some(prepared.summary.clone());s.prepared=Some(Arc::new(prepared));s.touched=Instant::now();Ok(())
    }
    pub fn refresh_data(&self,o:&Owner,id:&str)->Result<Vec<Vec<u8>>>{let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=Self::check(&mut r,id,o)?;if !matches!(s.state.phase.as_str(),"ready"|"stale"){return Err(fail("SESSION_NOT_READY"));}let data=s.prepared.as_ref().ok_or_else(||fail("SESSION_NOT_READY"))?.ordered.clone();s.state.phase="verifying".into();s.state.preview_nonce=None;s.inflight=true;s.touched=Instant::now();Ok(data)}
    pub fn details(&self,o:&Owner,id:&str,section:&str,offset:usize)->Result<Details>{let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=Self::check(&mut r,id,o)?;if s.state.phase!="ready"{return Err(fail("SESSION_NOT_READY"));}let p=s.prepared.as_ref().ok_or_else(||fail("SESSION_NOT_READY"))?;let all=p.details.iter().filter(|d|d.section==section).collect::<Vec<_>>();if offset>all.len(){return Err(fail("INVALID_CURSOR"));}let items=all.iter().skip(offset).take(8).map(|d|(*d).clone()).collect::<Vec<_>>();let next=if offset+items.len()<all.len(){Some(offset+items.len())}else{None};s.touched=Instant::now();Ok(Details{items,next})}
    #[cfg(test)]pub(crate) fn age(&self,id:&str,absolute:Duration,idle:Duration){let mut r=self.registry.lock().unwrap();let s=r.sessions.get_mut(id).unwrap();s.created=Instant::now()-absolute;s.touched=Instant::now()-idle;}
    pub fn confirm(self:&Arc<Self>,o:&Owner,id:&str,nonce:&str)->Result<State>{
        self.management_enabled()?;let(p,kind,operation)={let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=Self::check(&mut r,id,o)?;if matches!(s.state.phase.as_str(),"confirming"|"committed"){return Ok(s.state.clone());}if s.state.phase=="unknown"{return Err(fail("RECONCILE_OPERATION_FIRST"));}if s.state.phase=="expired"{return Err(fail("SESSION_EXPIRED"));}if s.state.phase!="ready"{return Err(fail("SESSION_NOT_READY"));}if s.state.preview_nonce.as_deref()!=Some(nonce){return Err(fail("PREVIEW_NONCE_MISMATCH"));}let work=self.heavy.compare_exchange(false,true,Ordering::AcqRel,Ordering::Acquire).map_err(|_|fail("BUSY"))?;let _=work;s.state.phase="confirming".into();s.inflight=true;(s.prepared.clone().ok_or_else(||fail("SESSION_NOT_READY"))?,s.kind,s.state.operation_id.clone())};let _work=Work(self.clone());
        let result=(||->Result<Receipt>{let mut generation=p.summary.generation;if p.summary.repository_id.is_none(){if kind!=Kind::Trust||self.repository.inspect_presence()?!= "absent"{return Err(fail("STALE_GENERATION"));}generation=self.repository.initialize_new()?.generation;}else{let current=self.repository.open_existing()?;if Some(current.repository_id)!=p.summary.repository_id||current.generation!=generation{return Err(fail("STALE_GENERATION"));}}
            if kind==Kind::Trust{Ok(self.repository.accept_trust_episode(&operation,generation,&p.ordered)?)}else{Ok(self.repository.record_verified_installation(&operation,generation,&p.ordered[0],&p.operations)?)}
        })();
        let result=match result{Ok(v)=>Ok(v),Err(e)=>match self.repository.operation_status(&operation){Ok(Some(v))=>Ok(v),Ok(None)=>Err(e),Err(_) if matches!(e.code.as_str(),"COMMIT_OUTCOME_UNKNOWN"|"COMMITTED_RECOVERY_PENDING")=>Err(fail("COMMIT_OUTCOME_UNKNOWN")),Err(_)=>Err(e)}};
        let mut r=self.registry.lock().map_err(|_|fail("UNAVAILABLE"))?;let s=r.sessions.get_mut(id).ok_or_else(||fail("SESSION_UNKNOWN"))?;s.inflight=false;match result{Ok(receipt)=>{s.state.phase="committed".into();s.state.receipt=Some(receipt);s.prepared=None;s.reservation=0;},Err(e)=>{s.state.error=Some(e.code.clone());s.state.phase=if e.code=="STALE_GENERATION"{"stale"}else if matches!(e.code.as_str(),"COMMIT_OUTCOME_UNKNOWN"|"COMMITTED_RECOVERY_PENDING"){"unknown"}else{"rejected"}.into();if s.state.phase=="rejected"{s.prepared=None;s.reservation=0;}}}Ok(s.state.clone())
    }
}
